import React, {useEffect, useRef, useState} from "react";
import {createRoot} from "react-dom/client";
import {QRCodeSVG} from "qrcode.react";
import "./style.css";

type Media={id:string,title:string,year?:number,summary:string,genres:string[],duration:number,rating?:string,poster_url?:string,available?:boolean,edition_title?:string,unwatched_count?:number,version_count?:number,top_choice?:boolean,second_chance?:boolean,second_chance_prompt?:string};
type Room={code:string,status:string,kind:string,mode:string,phase:"genres"|"movies"|"second_chance",filter_type?:string,filter_value?:string,participants:{id:string,name:string}[],match?:Media,join_url?:string,allow_undo:boolean,offer_another_match:boolean,card_limit?:number,top_choice_count?:number};
type TopChoiceStatus={limit:number,used:number,remaining:number};
type Settings={movies_enabled:boolean,shows_enabled:boolean,random_enabled:boolean,filter_enabled:boolean,genre_match_enabled:boolean,random_pool_size:number,allowed_content_ratings:string[],undo_enabled:boolean,another_match_enabled:boolean,finite_sessions_enabled:boolean,finite_card_limit:number,reset_room_choices:boolean,matched_item_cooldown_days:number};
type RoomPreferences={kind:string,mode:string,filter_type?:string,filter_value?:string,remembered:boolean};
type RoomDraft={kind:string,mode:string,filterType:string,filterValue:string,recencyBasis:string,recencyUnwatched:boolean};
type LibraryOption={library:string,kind:"movie"|"show",count:number};
type MatchHistoryItem={id:number,title:string,year?:number,kind?:string,available:boolean,matched_at:string,eligible_at:string,eligible:boolean};
const defaultSettings:Settings={movies_enabled:true,shows_enabled:true,random_enabled:true,filter_enabled:true,genre_match_enabled:true,random_pool_size:100,allowed_content_ratings:[],undo_enabled:false,another_match_enabled:false,finite_sessions_enabled:false,finite_card_limit:25,reset_room_choices:false,matched_item_cooldown_days:7};
const roomDraftKey="watchmatch-room-draft-v1";
const readRoomDraft=():RoomDraft|null=>{try{const value=JSON.parse(localStorage.getItem(roomDraftKey)||"null");return value&&typeof value.kind==="string"&&typeof value.mode==="string"&&typeof value.filterType==="string"?value:null}catch{return null}};
const api=async(path:string,options?:RequestInit)=>{const r=await fetch(path,{headers:{"Content-Type":"application/json"},...options});const text=await r.text();let data:any={};try{data=text?JSON.parse(text):{}}catch{if(!r.ok)throw new Error(`Request failed (${r.status})`);throw new Error("The server returned an invalid response")};if(!r.ok)throw new Error(data.detail||`Request failed (${r.status})`);return data};
function socket(code:string,setRoom:(r:Room)=>void){const protocol=location.protocol==="https:"?"wss":"ws";const ws=new WebSocket(`${protocol}://${location.host}/ws/rooms/${code}`);ws.onmessage=e=>{const m=JSON.parse(e.data);if(m.type==="room")setRoom(m.data)};return()=>ws.close()}

function Home(){
  const [initialDraft]=useState<RoomDraft|null>(readRoomDraft);
  const [settings,setSettings]=useState<Settings>(defaultSettings);
  const [kind,setKind]=useState(initialDraft?.kind||"movie");
  const [mode,setMode]=useState(initialDraft?.mode||"random");
  const [filterType,setFilterType]=useState(initialDraft?.filterType||"genre");
  const [filterValue,setFilterValue]=useState(initialDraft?.filterValue||"");
  const [recencyBasis,setRecencyBasis]=useState(initialDraft?.recencyBasis||"released");
  const [recencyUnwatched,setRecencyUnwatched]=useState(initialDraft?.recencyUnwatched||false);
  const [draftReady,setDraftReady]=useState(false);
  const [options,setOptions]=useState<string[]>([]);
  const [filterFocused,setFilterFocused]=useState(false);
  const [optionsLoading,setOptionsLoading]=useState(false);
  const [libraries,setLibraries]=useState<LibraryOption[]>([]);
  const [library,setLibrary]=useState("");
  const [librarySelectionRequired,setLibrarySelectionRequired]=useState(false);
  const [roomCode,setRoomCode]=useState("");
  const [error,setError]=useState("");
  const [creating,setCreating]=useState(false);
  const loadRoomDefaults=()=>Promise.all([api("/api/settings"),api("/api/room-preferences")]).then(([value,preference]:[Settings,RoomPreferences])=>{setSettings(value);if(!initialDraft){setKind(preference.kind);setMode(preference.mode);if(preference.filter_type){setFilterType(preference.filter_type);const saved=preference.filter_value||"";if(preference.filter_type==="recency"){const [basis,gate]=saved.split(":");setRecencyBasis(basis||"released");setRecencyUnwatched(gate==="unwatched")}else setFilterValue(saved)}}}).catch(()=>{}).finally(()=>setDraftReady(true));
  useEffect(()=>{loadRoomDefaults();api("/api/room-libraries").then((value:LibraryOption[])=>setLibraries(value)).catch(()=>{});api("/api/room-library-policy").then((value:{selection_required:boolean})=>setLibrarySelectionRequired(value.selection_required)).catch(()=>{});const authenticated=()=>{setError("");api("/api/settings").then(setSettings).catch(()=>{})};window.addEventListener("watchmatch-authenticated",authenticated);return()=>window.removeEventListener("watchmatch-authenticated",authenticated)},[]);
  useEffect(()=>{if(librarySelectionRequired)return;api(`/api/room-library-policy?kind=${kind}`).then((value:{default_library?:string})=>{if(value.default_library)setLibrary(value.default_library)}).catch(()=>{})},[kind,librarySelectionRequired]);
  const librariesForKind=libraries.filter(item=>item.kind===kind);
  // The legacy room form predates selectable libraries. Keep its V1 default
  // untouched unless an owner has explicitly turned library selection on.
  useEffect(()=>{const previous=document.querySelector(".room-library-picker");previous?.remove();if(!librarySelectionRequired||librariesForKind.length<2)return;const anchor=document.querySelector(".media-kind");if(!anchor)return;const field=document.createElement("label");field.className="room-library-picker";field.textContent="Plex library";const select=document.createElement("select");select.setAttribute("aria-label","Plex library");for(const item of librariesForKind){const option=document.createElement("option");option.value=item.library;option.textContent=`${item.library} · ${item.count} titles`;option.selected=item.library===library;select.append(option)}select.onchange=()=>{setLibrary(select.value);setFilterValue("");setOptions([])};field.append(select);anchor.after(field);return()=>field.remove()},[librarySelectionRequired,librariesForKind,library]);
  useEffect(()=>{if(librarySelectionRequired&&librariesForKind.length&& !librariesForKind.some(item=>item.library===library))setLibrary(librariesForKind[0].library)},[kind,libraries,library,librarySelectionRequired]);
  useEffect(()=>{if(draftReady)localStorage.setItem(roomDraftKey,JSON.stringify({kind,mode,filterType,filterValue,recencyBasis,recencyUnwatched}))},[draftReady,kind,mode,filterType,filterValue,recencyBasis,recencyUnwatched]);
  useEffect(()=>{const button=document.querySelector<HTMLButtonElement>(".create-room");if(button){button.disabled=creating;button.textContent=creating?"Creating room…":"Create room";button.setAttribute("aria-busy",String(creating))}},[creating]);
  useEffect(()=>{if(kind==="show"&&filterType==="runtime"){setFilterType("genre");setFilterValue("")}},[kind,filterType]);
  useEffect(()=>{if(mode!=="filter"||["runtime","recency"].includes(filterType)||!library)return;const minimum=filterType==="genre"?0:2;if(filterValue.length<minimum){setOptions([]);setOptionsLoading(false);return}const controller=new AbortController();const timer=setTimeout(async()=>{setOptionsLoading(true);try{setOptions(await api(`/api/filter-options?kind=${kind}&library=${encodeURIComponent(library)}&filter_type=${filterType}&q=${encodeURIComponent(filterValue)}`,{signal:controller.signal}))}catch(e){if(!controller.signal.aborted)setOptions([])}finally{if(!controller.signal.aborted)setOptionsLoading(false)}},250);return()=>{clearTimeout(timer);controller.abort()}},[mode,kind,library,filterType,filterValue]);
  const effectiveFilterValue=filterType==="recency"?`${recencyBasis}:${recencyUnwatched?"unwatched":"any"}`:filterValue;
  const create=async()=>{if(creating)return;if(!library&&libraries.length)return setError("Choose a Plex library.");if(mode==="filter"&&!effectiveFilterValue.trim())return setError("Choose or enter a filter value.");setCreating(true);setError("");try{const room=await api("/api/rooms",{method:"POST",body:JSON.stringify({kind,library:library||null,mode,filter_type:mode==="filter"?filterType:null,filter_value:mode==="filter"?effectiveFilterValue.trim():null})});if(settings.reset_room_choices)localStorage.removeItem(roomDraftKey);const invite=new URL(room.join_url).searchParams.get("invite");location.href=`/room/${room.code}${invite?`?invite=${encodeURIComponent(invite)}`:""}`}catch(e){setError(e instanceof Error?e.message:"Could not create room");setCreating(false)}};
  const join=async()=>{const code=roomCode.trim().toUpperCase();if(code.length!==6)return setError("Enter the six-character room code.");try{await api(`/api/rooms/${code}`);location.href=`/join/${code}`}catch(e){setError(e instanceof Error?e.message:"Room not found")}};
  const choices=[{id:"random",enabled:settings.random_enabled,icon:"↝",title:"Surprise me",sub:settings.random_pool_size===0?"All eligible titles":`${settings.random_pool_size} random titles`},{id:"filter",enabled:settings.filter_enabled,icon:"☷",title:"Choose filters",sub:"Genre, collection, people, runtime, or recency"},{id:"genre_match",enabled:settings.genre_match_enabled,icon:"♡",title:"Match a genre",sub:"Swipe together, then pick a title"}].filter(c=>c.enabled);
  return <main className="center home"><div className="brand">WATCH<span>MATCH</span></div><h1>What sounds good<br/>tonight?</h1><p>Choose how you want to narrow down the {kind==="movie"?"Movies":"TV Shows"} library.</p><div className="mode-list">{choices.map(c=><button key={c.id} className={`mode-card ${mode===c.id?"selected":""}`} onClick={()=>{setMode(c.id);setError("")}}><span className="mode-icon">{c.icon}</span><span><b>{c.title}</b><small>{c.sub}</small></span><i>{mode===c.id?"✓":""}</i></button>)}</div>{mode==="filter"&&<section className="filter-panel"><select value={filterType} onChange={e=>{setFilterType(e.target.value);setFilterValue("");setOptions([])}}><option value="genre">Genre</option><option value="collection">Plex collection</option><option value="director">Director</option><option value="actor">Actor</option><option value="studio">Studio</option><option value="runtime">Runtime</option><option value="recency">Recency</option></select>{filterType==="runtime"?<select aria-label="Runtime" value={filterValue} onChange={e=>setFilterValue(e.target.value)}><option value="">Choose a runtime</option><option value="under_90">Under 90 minutes</option><option value="90_120">90–120 minutes</option><option value="120_150">2–2½ hours</option><option value="over_150">Over 2½ hours</option></select>:filterType==="recency"?<div className="recency-options"><select aria-label="Recency type" value={recencyBasis} onChange={e=>setRecencyBasis(e.target.value)}><option value="released">Released in the last year</option><option value="added">Added to Plex in the last 90 days</option><option value="both">Recently released or added</option></select><label><input type="checkbox" checked={recencyUnwatched} onChange={e=>setRecencyUnwatched(e.target.checked)}/> Unwatched only</label></div>:<div className="autocomplete"><input role="combobox" aria-expanded={filterFocused} aria-controls="filter-results" value={filterValue} autoComplete="off" onFocus={()=>setFilterFocused(true)} onBlur={()=>setTimeout(()=>setFilterFocused(false),150)} onChange={e=>{setFilterValue(e.target.value);setFilterFocused(true)}} placeholder={filterType==="genre"?"Choose or search genres":"Type at least 2 characters"}/>{filterFocused&&<div className="autocomplete-menu" id="filter-results" role="listbox">{optionsLoading?<div className="autocomplete-note">Searching…</div>:filterType!=="genre"&&filterValue.length<2?<div className="autocomplete-note">Type 2 or more characters to search</div>:options.length?options.map(x=><button type="button" role="option" key={x} onMouseDown={()=>{setFilterValue(x);setFilterFocused(false)}}>{x}</button>):<div className="autocomplete-note">No matches found</div>}</div>}</div>}</section>}<div className="seg media-kind">{settings.movies_enabled&&<button className={kind==="movie"?"active":""} onClick={()=>setKind("movie")}>◉ Movies</button>}{settings.shows_enabled&&<button className={kind==="show"?"active":""} onClick={()=>setKind("show")}>▣ TV Shows</button>}</div>{error&&<div className="form-error">{error}</div>}<button className="primary create-room" onClick={create}>Create room</button><div className="or"><span>or join an existing room</span></div><section className="join-code"><h2>Have a room code?</h2><div><input aria-label="Room code" value={roomCode} maxLength={6} autoCapitalize="characters" onChange={e=>{setRoomCode(e.target.value.replace(/[^a-z0-9]/gi,"").toUpperCase());setError("")}} onKeyDown={e=>e.key==="Enter"&&join()} placeholder="ABC123"/><button onClick={join}>Join</button></div></section></main>
}
function RoomView({code}:{code:string}){
  const [room,setRoom]=useState<Room|null>(null);
  const [shareStatus,setShareStatus]=useState("");
  useEffect(()=>{api(`/api/rooms/${code}`).then(setRoom);return socket(code,setRoom)},[]);
  const invite=new URLSearchParams(location.search).get("invite");
  const join=`${location.origin}/join/${code}${invite?`?invite=${encodeURIComponent(invite)}`:""}`;
  const share=async()=>{const data={title:"Join my WatchMatch room",text:`Join room ${code} and help pick what we watch:`,url:join};const canShare=typeof navigator.share==="function";try{if(canShare)await navigator.share(data);else await navigator.clipboard.writeText(join);setShareStatus(canShare?"Invite shared":"Link copied")}catch(e){if(e instanceof Error&&e.name!=="AbortError"){const el=document.createElement("textarea");el.value=join;document.body.appendChild(el);el.select();document.execCommand("copy");el.remove();setShareStatus("Link copied")}}};
  if(!room)return <main>Loading…</main>;
  const another=async()=>setRoom(await api(`/api/rooms/${code}/another-match`,{method:"POST"}));
  if(room.match)return <Match media={room.match} room={room} display onContinue={another}/>;
  if(room.status==="exhausted")return <Exhausted/>;
  return <main className="tv"><header><div className="brand">WATCH<span>MATCH</span></div><button className="start-over" onClick={()=>location.href="/"}>＋ Create a new room</button></header><section><div><div className="eyebrow">ROOM {code}</div><h1>Your room<br/>is ready.</h1><p>{room.participants.length}/2 players joined</p><div className="people">{[0,1].map(i=><div className={room.participants[i]?"joined":""} key={i}>{room.participants[i]?.name||`Waiting for player ${i+1}`}</div>)}</div><div className="creator-actions"><button className="primary" onClick={()=>location.href=`/join/${code}`}>Join on this device</button><button className="share-button" onClick={share}>↗ Share invite</button></div>{shareStatus&&<div className="share-status">✓ {shareStatus}</div>}<p className="display-note">Leave this page open to use this device as the room display.</p></div><div className="qr"><QRCodeSVG value={join} size={230}/><b>{code}</b><small>Scan, share, or enter the room code</small><span>{join}</span></div></section></main>
}
function Join({code}:{code:string}){
  const [name,setName]=useState("");
  const [pid,setPid]=useState(localStorage.getItem(`wm-${code}`)||"");
  const [room,setRoom]=useState<Room|null>(null);
  const [cards,setCards]=useState<Media[]>([]);
  const [genres,setGenres]=useState<string[]>([]);
  const [drag,setDrag]=useState({active:false,startX:0,startY:0,x:0,y:0});
  const dragRef=useRef({active:false,startX:0,startY:0,x:0,y:0});
  const loadVersion=useRef(0);
  const swipeInFlight=useRef(false);
  const [topChoices,setTopChoices]=useState<TopChoiceStatus>({limit:0,used:0,remaining:0});
  const [shareStatus,setShareStatus]=useState("");
  const [canUndo,setCanUndo]=useState(false);
  const load=async(id:string,phase="movies")=>{const version=++loadVersion.current;if(phase==="genres"){const nextGenres=await api(`/api/rooms/${code}/genres?participant_id=${id}`);if(version===loadVersion.current)setGenres(nextGenres)}else{const [nextCards,status]=await Promise.all([api(`/api/rooms/${code}/cards?participant_id=${id}`),api(`/api/rooms/${code}/top-choice-status?participant_id=${id}`)]);if(version===loadVersion.current){setCards(nextCards);setTopChoices(status)}}};
  useEffect(()=>{if(pid){api(`/api/rooms/${code}`).then(setRoom);return socket(code,setRoom)}},[pid]);
  useEffect(()=>{if(pid&&room?.participants.length===2)load(pid,room.phase)},[pid,room?.participants.length,room?.phase,room?.top_choice_count]);
  const join=async()=>{const x=await api(`/api/rooms/${code}/join`,{method:"POST",body:JSON.stringify({name})});localStorage.setItem(`wm-${code}`,x.participant_id);setPid(x.participant_id)};
  const shareInvite=async()=>{const url=location.href;const data={title:"Join my WatchMatch room",text:`Join room ${code} and help pick what we watch:`,url};try{if(navigator.share){await navigator.share(data);setShareStatus("Invite shared")}else{await copyInvite(url)}}catch(e){if(e instanceof Error&&e.name!=="AbortError")await copyInvite(url)}};
  const copyInvite=async(url:string)=>{try{await navigator.clipboard.writeText(url)}catch{const el=document.createElement("textarea");el.value=url;document.body.appendChild(el);el.select();document.execCommand("copy");el.remove()}setShareStatus("Invite link copied")};
  const swipe=async(direction:string)=>{const isGenre=room?.phase==="genres";const card=cards[0];const genre=genres[0];const resting={active:false,startX:0,startY:0,x:0,y:0};dragRef.current=resting;setDrag(resting);if(swipeInFlight.current||isGenre&&!genre||!isGenre&&!card||direction==="top"&&(isGenre||topChoices.remaining<=0))return;swipeInFlight.current=true;loadVersion.current++;if(isGenre)setGenres(g=>g.slice(1));else{setCards(c=>c.slice(1));if(direction==="top")setTopChoices(s=>({...s,used:s.used+1,remaining:Math.max(0,s.remaining-1)}))}try{const r=await api(`/api/rooms/${code}/swipe`,{method:"POST",body:JSON.stringify({participant_id:pid,media_id:isGenre?`genre:${genre}`:card.id,direction})});setRoom(r);if(!isGenre)setCanUndo(true)}catch{await load(pid,isGenre?"genres":"movies")}finally{swipeInFlight.current=false}};
  const undoSwipe=async()=>{const r=await api(`/api/rooms/${code}/undo`,{method:"POST",body:JSON.stringify({participant_id:pid})});setRoom(r);setCanUndo(false);await load(pid,"movies")};
  const another=async()=>{const r=await api(`/api/rooms/${code}/another-match`,{method:"POST"});setRoom(r);setCanUndo(false);if(r.status==="open")await load(pid,"movies")};
  const pointerDown=(e:React.PointerEvent)=>{e.currentTarget.setPointerCapture(e.pointerId);const next={active:true,startX:e.clientX,startY:e.clientY,x:0,y:0};dragRef.current=next;setDrag(next)};
  const pointerMove=(e:React.PointerEvent)=>{const current=dragRef.current;if(current.active){const next={...current,x:e.clientX-current.startX,y:e.clientY-current.startY};dragRef.current=next;setDrag(next)}};
  const pointerUp=(event?:React.PointerEvent)=>{const current=dragRef.current;const resting={active:false,startX:0,startY:0,x:0,y:0};dragRef.current=resting;if(event?.type==="pointercancel")return setDrag(resting);if(room?.phase==="movies"&&current.y<=-80&&Math.abs(current.y)>Math.abs(current.x))swipe("top");else if(Math.abs(current.x)>=80)swipe(current.x>0?"right":"left");else setDrag(resting)};
  if(!pid)return <main className="center"><div className="brand">WATCH<span>MATCH</span></div><div className="eyebrow">JOIN ROOM {code}</div><h1>What's your name?</h1><input autoFocus value={name} onChange={e=>setName(e.target.value)} onKeyDown={e=>e.key==="Enter"&&name&&join()} placeholder="Your name"/><button className="primary" disabled={!name.trim()} onClick={join}>Start swiping</button></main>;
  if(room?.match)return <Match media={room.match} room={room} onContinue={another}/>;
  if(room?.status==="exhausted")return <Exhausted/>;
  if(!room||room.participants.length<2)return <main className="center waiting"><div className="brand">WATCH<span>MATCH</span></div><div className="waiting-pulse">♥</div><div className="eyebrow">YOU'RE IN</div><h1>Waiting for<br/>the other player.</h1><p>Cards will appear as soon as they join room <strong>{code}</strong>.</p><div className="lobby-qr"><QRCodeSVG value={`${location.origin}/join/${code}`} size={180}/><small>Let them scan this phone</small></div><div className="lobby-actions"><button className="share-button" onClick={shareInvite}><span>↗</span> Share invite</button><button className="start-over" onClick={()=>location.href="/"}>＋ Create a new room</button></div>{shareStatus&&<div className="share-status">✓ {shareStatus}</div>}<small className="invite-url">{location.origin}/join/{code}</small></main>;
  if(room.phase==="genres"){
    const genre=genres[0];
    if(!genre)return <main className="center"><h2>No genres left</h2><p>Waiting to see whether your partner creates a match.</p></main>;
    return <main className="swipe genre-swipe"><div className="top"><div className="brand">W<span>M</span></div><div className="room-nav"><span>ROOM {code}</span><button onClick={()=>location.href="/"}>← Leave room</button></div></div><div className="phase-label">MATCH A GENRE</div><article className={drag.active?"dragging":""} style={{transform:`translateX(${drag.x}px) rotate(${drag.x/25}deg)`}} onPointerDown={pointerDown} onPointerMove={pointerMove} onPointerUp={pointerUp} onPointerCancel={pointerUp}><div className={`swipe-ghost ${drag.x<0?"pass":drag.x>0?"like":""}`} style={{opacity:Math.min(Math.abs(drag.x)/180,.46)}}/><div className={`vote vote-no ${drag.x<-25?"visible":""}`}>NOPE</div><div className={`vote vote-yes ${drag.x>25?"visible":""}`}>YES</div><div className="genre-card"><span>TONIGHT'S MOOD</span><h2>{genre}</h2><p>Would you watch a {genre.toLowerCase()} title tonight?</p></div></article><div className="actions"><button aria-label="Pass" className="no" onClick={()=>swipe("left")}>×</button><button aria-label="Like" className="yes" onClick={()=>swipe("right")}>♥</button></div><div className="swipe-hint">First mutual genre wins</div></main>
  }
  const card=cards[0];
  if(!card)return <main className="center"><h2>You're all caught up</h2><p>Waiting for your match—or more titles.</p>{room.allow_undo&&room.phase==="movies"&&<button className="undo-swipe" disabled={!canUndo} onClick={undoSwipe}>↶ Undo last swipe</button>}</main>;
  return <main className="swipe"><div className="top"><div className="brand">W<span>M</span></div><div className="room-nav"><span>ROOM {code}</span><button onClick={()=>location.href="/"}>← Leave room</button></div></div>{room.phase==="second_chance"&&<div className="second-chance-heading"><b>SECOND CHANCE</b><span>Take another look at titles someone else wanted.</span></div>}<article className={drag.active?"dragging":""} style={{transform:`translate(${drag.x}px, ${drag.y}px) rotate(${drag.x/25}deg)`}} onPointerDown={pointerDown} onPointerMove={pointerMove} onPointerUp={pointerUp} onPointerCancel={pointerUp}><div className={`swipe-ghost ${drag.x<0?"pass":drag.x>0?"like":""}`} style={{opacity:Math.min(Math.abs(drag.x)/180,.46)}}/><div className={`vote vote-no ${drag.x<-25?"visible":""}`}>NOPE</div><div className={`vote vote-yes ${drag.x>25?"visible":""}`}>YES</div><div className={`vote vote-top ${drag.y<-25&&Math.abs(drag.y)>Math.abs(drag.x)?"visible":""}`}>TOP CHOICE</div>{card.second_chance&&<div className="second-chance-badge">{card.second_chance_prompt}</div>}{card.top_choice&&<div className="top-choice-badge">★ TOP CHOICE</div>}{card.poster_url?<img src={card.poster_url} draggable={false}/>:<div className="poster">{card.title[0]}</div>}<div className="info"><h2>{card.title} <small>{card.year}</small></h2><div className="meta">{card.rating} {card.duration?` · ${Math.round(card.duration/60)} min`:""}</div><p>{card.summary}</p><div>{card.genres.map(g=><span className="tag" key={g}>{g}</span>)}</div></div></article><div className="actions"><button aria-label="Pass" className="no" onClick={()=>swipe("left")}>×</button>{room.phase==="movies"&&<button aria-label={`Top Choice, ${topChoices.remaining} remaining`} className="top-choice" disabled={topChoices.remaining<=0} onClick={()=>swipe("top")}><span>★</span><small>{topChoices.remaining}</small></button>}<button aria-label="Like" className="yes" onClick={()=>swipe("right")}>♥</button></div>{room.allow_undo&&room.phase==="movies"&&<button className="undo-swipe" disabled={!canUndo} onClick={undoSwipe}>↶ Undo last swipe</button>}<div className="swipe-hint">{room.phase==="second_chance"?"A new yes can create the match":"Swipe left to pass · up for Top Choice · right to like"}</div></main>
}
function Exhausted(){return <main className="match exhausted"><div className="burst">↻</div><div className="eyebrow">THAT'S THE WHOLE STACK</div><h1>No match<br/>this time.</h1><p>You both voted on every available title in this room.</p><button className="primary" onClick={()=>location.href="/"}>Create a new room</button></main>}
function Match({media,room,display=false,onContinue}:{media:Media,room:Room,display?:boolean,onContinue:()=>void}){return <main className={`match ${display?"display-match":""}`}>{display&&media.poster_url&&<img className="match-poster" src={media.poster_url}/>}<div className="match-copy"><div className="burst">♥</div><div className="eyebrow">IT'S A MATCH</div><h1>Tonight you're watching<br/><span>{media.title}{media.edition_title?` — ${media.edition_title}`:""}</span></h1><p>{media.year} · {media.genres.join(" · ")}</p>{media.available===false&&<div className="availability-warning">This title is no longer available in Plex.</div>}{!display&&<div className="match-actions">{room.offer_another_match&&<button className="primary another-match" onClick={onContinue}>Find another match</button>}<button className={room.offer_another_match?"start-over":"primary"} onClick={()=>location.href="/"}>Start a new room</button></div>}</div></main>}
function Toggle({checked,onChange,label,description}:{checked:boolean,onChange:(value:boolean)=>void,label:string,description:string}){return <label className="setting-row"><span><b>{label}</b><small>{description}</small></span><input type="checkbox" checked={checked} onChange={e=>onChange(e.target.checked)}/><i aria-hidden="true"/></label>}

function Admin({system=false}:{system?:boolean}){
  const [section,setSection]=useState(system?"catalog":"rooms");
  const [movie,setMovie]=useState(true),[shows,setShows]=useState(true);
  const [surprise,setSurprise]=useState(true),[filters,setFilters]=useState(true),[genreMatch,setGenreMatch]=useState(true);
  const [undo,setUndo]=useState(false),[another,setAnother]=useState(false),[finite,setFinite]=useState(false);
  const [resetChoices,setResetChoices]=useState(false),[cooldownDays,setCooldownDays]=useState(7);
  const [poolSize,setPoolSize]=useState(100),[cardLimit,setCardLimit]=useState(25);
  const [ratings,setRatings]=useState(["G","PG","PG-13","R"]);
  const [sync,setSync]=useState<any>(null);
  const [syncInterval,setSyncInterval]=useState(1440),[syncStatus,setSyncStatus]=useState("");
  const [libraryCatalog,setLibraryCatalog]=useState<any[]>([]),[selectableLibraries,setSelectableLibraries]=useState<string[]>([]),[libraryStatus,setLibraryStatus]=useState("");
  const [history,setHistory]=useState<MatchHistoryItem[]>([]),[historyStatus,setHistoryStatus]=useState("");
  const [accounts,setAccounts]=useState<any>(null),[recoveryHousehold,setRecoveryHousehold]=useState(""),[recoveryUser,setRecoveryUser]=useState(""),[recoveryStatus,setRecoveryStatus]=useState("");
  const [loaded,setLoaded]=useState(system),[saving,setSaving]=useState(false),[saveStatus,setSaveStatus]=useState("");
  const refreshSync=()=>api("/api/sync/status").then((value:any)=>{setSync(value);setSyncInterval(value.interval_minutes)}).catch(()=>{});
  const refreshHistory=()=>api("/api/match-history").then(setHistory).catch(()=>{});
  useEffect(()=>{if(system){refreshSync();api("/api/system/libraries").then((value:any)=>{setLibraryCatalog(value.catalog);setSelectableLibraries(value.selectable_libraries)}).catch(()=>{});const timer=setInterval(refreshSync,10000);api("/api/system/accounts").then((value:any)=>{setAccounts(value);if(value.households[0])setRecoveryHousehold(String(value.households[0].id));if(value.users[0])setRecoveryUser(String(value.users[0].id))}).catch(()=>{});return()=>clearInterval(timer)}},[system]);
  useEffect(()=>{if(system)return;api("/api/settings").then((value:Settings)=>{setMovie(value.movies_enabled);setShows(value.shows_enabled);setSurprise(value.random_enabled);setFilters(value.filter_enabled);setGenreMatch(value.genre_match_enabled);setPoolSize(value.random_pool_size);setRatings(value.allowed_content_ratings);setUndo(value.undo_enabled);setAnother(value.another_match_enabled);setFinite(value.finite_sessions_enabled);setCardLimit(value.finite_card_limit);setResetChoices(value.reset_room_choices);setCooldownDays(value.matched_item_cooldown_days);setLoaded(true)}).catch(e=>setSaveStatus(e instanceof Error?e.message:"Could not load settings"));refreshHistory()},[system]);
  const save=async()=>{setSaving(true);setSaveStatus("");try{await api("/api/settings",{method:"PUT",body:JSON.stringify({movies_enabled:movie,shows_enabled:shows,random_enabled:surprise,filter_enabled:filters,genre_match_enabled:genreMatch,random_pool_size:poolSize,allowed_content_ratings:ratings,undo_enabled:undo,another_match_enabled:another,finite_sessions_enabled:finite,finite_card_limit:cardLimit,reset_room_choices:resetChoices,matched_item_cooldown_days:cooldownDays})});setSaveStatus("Settings saved")}catch(e){setSaveStatus(e instanceof Error?e.message:"Could not save settings")}finally{setSaving(false)}};
  const recoverAccount=async()=>{if(!recoveryHousehold||!recoveryUser)return;const household=accounts?.households.find((x:any)=>String(x.id)===recoveryHousehold);const user=accounts?.users.find((x:any)=>String(x.id)===recoveryUser);if(!confirm(`Assign ${user?.username} to ${household?.name}? Existing sessions for affected accounts will be revoked.`))return;setRecoveryStatus("");try{await api(`/api/system/households/${recoveryHousehold}/recover`,{method:"POST",body:JSON.stringify({user_id:Number(recoveryUser)})});setRecoveryStatus(`Recovered ${household?.name} for ${user?.username}. Affected sessions were signed out.`)}catch(e){setRecoveryStatus(e instanceof Error?e.message:"Recovery failed")}};
  const startSync=async()=>{setSyncStatus("");try{const value=await api("/api/sync",{method:"POST"});setSyncStatus(value.accepted?"Plex synchronization started":"A synchronization is already running");refreshSync()}catch(e){setSyncStatus(e instanceof Error?e.message:"Could not start synchronization")}};
  const saveSyncSchedule=async()=>{setSyncStatus("");try{await api("/api/sync/settings",{method:"PUT",body:JSON.stringify({interval_minutes:syncInterval})});setSyncStatus("Synchronization schedule saved");refreshSync()}catch(e){setSyncStatus(e instanceof Error?e.message:"Could not save schedule")}};
  const saveLibraries=async()=>{setLibraryStatus("");try{const value=await api("/api/system/libraries",{method:"PUT",body:JSON.stringify({libraries:selectableLibraries})});setSelectableLibraries(value.selectable_libraries);setLibraryStatus(value.selectable_libraries.length?"Selectable libraries saved":"All non-excluded synchronized libraries remain available (V1 default)")}catch(e){setLibraryStatus(e instanceof Error?e.message:"Could not save libraries")}};
  const restoreHistory=async(item:MatchHistoryItem)=>{if(!confirm(`Return ${item.title} to the eligible pool now? Its match-history entries will be removed.`))return;await api(`/api/match-history/${item.id}/restore`,{method:"POST"});setHistoryStatus(`${item.title} returned to the pool`);refreshHistory()};
  const clearHistory=async()=>{if(!confirm("Clear all household match history? This cannot be undone."))return;const value=await api("/api/match-history",{method:"DELETE"});setHistoryStatus(`${value.removed} match${value.removed===1?"":"es"} cleared`);refreshHistory()};
  const nav=system?[{id:"catalog",icon:"▦",label:"Catalog & Plex"},{id:"accounts",icon:"⌾",label:"Account recovery"}]:[{id:"rooms",icon:"⌂",label:"Rooms"},{id:"selection",icon:"♡",label:"Selection"},{id:"history",icon:"↺",label:"Match history"},{id:"access",icon:"⌾",label:"Access"}];
  const ratingOptions=["G","PG","PG-13","R","NC-17","NR"];
  return <main className="admin-shell">
    <aside className="admin-nav"><a className="brand" href="/">WATCH<span>MATCH</span></a><div className="admin-kicker">{system?"SYSTEM CONSOLE":"ADMIN CONSOLE"}</div><nav>{nav.map(item=><button key={item.id} className={section===item.id?"active":""} onClick={()=>setSection(item.id)}><span>{item.icon}</span>{item.label}</button>)}</nav><div className="admin-nav-foot"><span className="status-dot"/>{system?"Owner authenticated":"Settings connected"}<small>{system?"Platform operations protected":"Saved in PostgreSQL"}</small></div></aside>
    <section className="admin-main"><header><div><div className="eyebrow">{system?"PLATFORM OPERATIONS":"HOUSEHOLD SETTINGS"}</div><h1>{nav.find(item=>item.id===section)?.label}</h1><p>{system?"Monitor the shared Plex catalog and WatchMatch infrastructure.":"Set the defaults people see when they create a WatchMatch room."}</p></div><div className="admin-header-actions"><a href="/">View app</a>{!system&&<button disabled={!loaded||saving} onClick={save}>{saving?"Saving…":"Save changes"}</button>}</div></header>
      <div className="preview-banner"><span>◈</span><div><b>{system?"Owner-only system console":saveStatus||"Household configuration"}</b><small>{system?"Plex owner authentication protects this page and its operational APIs.":"These settings persist and are copied into every newly created room."}</small></div></div>
      {section==="rooms"&&<div className="settings-stack">
        <SettingCard title="Available media" description="Choose what a room creator is allowed to browse."><div className="choice-grid"><Choice active={movie} icon="◉" title="Movies" onClick={()=>setMovie(!movie)}/><Choice active={shows} icon="▣" title="TV shows" onClick={()=>setShows(!shows)}/></div></SettingCard>
        <SettingCard title="Search types" description="Show or hide room-creation paths independently."><Toggle checked={surprise} onChange={setSurprise} label="Surprise me" description="Create a random pool from eligible titles."/><Toggle checked={filters} onChange={setFilters} label="Choose filters" description="Search by genre, creator, studio, or runtime."/><Toggle checked={genreMatch} onChange={setGenreMatch} label="Match a genre" description="Participants agree on a genre before titles appear."/></SettingCard>
        <SettingCard title="Room defaults" description="Starting values for every new room."><div className="field-grid"><Field label="Default media"><select defaultValue="movie"><option value="movie">Movies</option><option value="show">TV shows</option></select></Field></div><Toggle checked={resetChoices} onChange={setResetChoices} label="Reset to defaults for new rooms" description="Forget a creator's last room choices after creation and start from household defaults next time."/></SettingCard>
      </div>}
      {section==="selection"&&<div className="settings-stack">
        <SettingCard title="Surprise me" description="Control the size and makeup of random rooms."><Field label="Random title pool"><div className="number-field"><input type="number" min="0" value={poolSize} onChange={e=>setPoolSize(Number(e.target.value))}/><span>titles</span></div><small>Use 0 later to include the full eligible catalog.</small></Field></SettingCard>
        <SettingCard title="Participant controls" description="Optional actions available while people swipe."><Toggle checked={undo} onChange={setUndo} label="Allow undo" description="Let a participant reverse their most recent swipe."/><Toggle checked={another} onChange={setAnother} label="Offer another match" description="Keep the room together after its first successful match."/><Toggle checked={finite} onChange={setFinite} label="Finite sessions" description="Stop after a configured number of cards."/>{finite&&<Field label="Cards per session"><div className="number-field"><input type="number" min="1" value={cardLimit} onChange={e=>setCardLimit(Number(e.target.value))}/><span>cards</span></div></Field>}</SettingCard>
        <SettingCard title="Content ratings" description="Only eligible ratings will enter a room pool."><div className="rating-grid">{ratingOptions.map(rating=><button key={rating} className={ratings.includes(rating)?"active":""} onClick={()=>setRatings(current=>current.includes(rating)?current.filter(x=>x!==rating):[...current,rating])}>{rating}<span>{ratings.includes(rating)?"✓":""}</span></button>)}</div><small>Leave every rating unselected to allow all Plex rating values.</small></SettingCard>
      </div>}
      {section==="catalog"&&<div className="settings-stack">
        <div className="metric-grid"><Metric label="Last Plex sync" value={sync?.latest?.status==="completed"?"Complete":sync?.latest?.status||"Loading"} detail={sync?.latest?.item_count?`${sync.latest.item_count.toLocaleString()} titles processed`:"Checking status"}/><Metric label="Schedule" value={`${sync?.interval_minutes||1440} min`} detail="Runs safely in the background"/><Metric label="Connection" value="Healthy" detail="PostgreSQL 18 · Plex reachable"/></div>
        <SettingCard title="Selectable Plex libraries" description="Choose the libraries creators may use for new rooms. Leave every library unselected to retain V1 behavior: every non-excluded synchronized library remains available.">{libraryCatalog.map(item=><label className="library-row" key={item.library}><span><b>{item.library}</b><small>{item.count.toLocaleString()} titles · {Object.entries(item.kinds).map(([kind,count])=>String(count)+" "+(kind==="movie"?"movies":"TV shows")).join(" · ")}</small></span><input type="checkbox" checked={selectableLibraries.includes(item.library)} onChange={()=>setSelectableLibraries(current=>current.includes(item.library)?current.filter(name=>name!==item.library):[...current,item.library])}/></label>)}<button className="secondary-action" onClick={saveLibraries}>Save selectable libraries</button>{libraryStatus&&<div className="share-status">{libraryStatus}</div>}</SettingCard>
        <SettingCard title="Synchronization" description="Control the shared Plex catalog update schedule."><div className="field-grid"><Field label="Frequency"><select value={syncInterval} onChange={e=>setSyncInterval(Number(e.target.value))}><option value="360">Every 6 hours</option><option value="720">Every 12 hours</option><option value="1440">Once a day</option><option value="10080">Once a week</option></select><button className="secondary-action" onClick={saveSyncSchedule}>Save schedule</button></Field><Field label="Manual update"><button className="secondary-action" disabled={sync?.running} onClick={startSync}>{sync?.running?"Sync in progress…":"Sync now"}</button></Field></div>{syncStatus&&<div className="share-status">{syncStatus}</div>}</SettingCard>
        <SettingCard title="Recent synchronization runs" description="The ten most recent Plex catalog updates."><div className="sync-history">{sync?.history?.length?sync.history.map((run:any)=><div className="sync-run" key={run.id}><span className={`sync-state ${run.status}`}>{run.status}</span><b>{run.trigger}</b><small>{new Date(run.started_at).toLocaleString()}</small><em>{run.item_count} items · +{run.added_count} · {run.updated_count} updated · {run.removed_count} unavailable</em>{run.error&&<p>{run.error}</p>}</div>):<p>No synchronization runs recorded yet.</p>}</div></SettingCard>
      </div>}
      {section==="accounts"&&<div className="settings-stack">
        <SettingCard title="Household account recovery" description="Reconnect a household to a Plex identity that has already signed in to WatchMatch."><div className="field-grid"><Field label="Household"><select value={recoveryHousehold} onChange={e=>setRecoveryHousehold(e.target.value)}>{accounts?.households.map((x:any)=><option key={x.id} value={x.id}>{x.name} · {x.room_count} rooms · {x.match_count} matches</option>)}</select></Field><Field label="Plex account"><select value={recoveryUser} onChange={e=>setRecoveryUser(e.target.value)}>{accounts?.users.map((x:any)=><option key={x.id} value={x.id}>{x.username}</option>)}</select></Field></div><button className="secondary-action recovery-action" disabled={!accounts||!recoveryHousehold||!recoveryUser} onClick={recoverAccount}>Reassign household account</button>{recoveryStatus&&<div className="share-status">{recoveryStatus}</div>}<small>This preserves the household's rooms, settings, matches, and history. The selected account's old membership and all affected browser sessions are revoked.</small></SettingCard>
        <SettingCard title="Emergency owner access" description="If Plex authentication is unavailable, the server recovery code creates a 15-minute owner session."><p>Keep <code>SYSTEM_RECOVERY_CODE</code> in a password manager. It is configured only on the server and is never displayed here.</p></SettingCard>
      </div>}
      {section==="history"&&<div className="settings-stack"><SettingCard title="Matched-title cooldown" description="Keep a recent match out of new household room pools."><Field label="Cooldown period"><div className="number-field"><input type="number" min="0" max="3650" value={cooldownDays} onChange={e=>setCooldownDays(Number(e.target.value))}/><span>days</span></div><small>Use 0 to make matched titles immediately eligible again.</small></Field></SettingCard><SettingCard title="Previous matches" description="Review household matches or return a title to the pool before its cooldown expires."><div className="match-history">{history.length?history.map(item=><div className="match-history-row" key={item.id}><span><b>{item.title}{item.year?` (${item.year})`:""}</b><small>Matched {new Date(item.matched_at).toLocaleString()} · {item.eligible?"Eligible now":`Eligible ${new Date(item.eligible_at).toLocaleDateString()}`}</small></span><button onClick={()=>restoreHistory(item)}>Return to pool</button></div>):<p>No matches recorded for this household yet.</p>}</div>{historyStatus&&<div className="share-status">{historyStatus}</div>}{history.length>0&&<button className="danger-action" onClick={clearHistory}>Clear all match history</button>}</SettingCard></div>}
      {section==="access"&&<HouseholdAccess/>}
    </section>
  </main>
}
function SettingCard({title,description,children}:{title:string,description:string,children:React.ReactNode}){return <section className="setting-card"><header><h2>{title}</h2><p>{description}</p></header><div className="setting-content">{children}</div></section>}
function Choice({active,icon,title,onClick}:{active:boolean,icon:string,title:string,onClick:()=>void}){return <button className={`admin-choice ${active?"active":""}`} onClick={onClick}><span>{icon}</span><b>{title}</b><i>{active?"✓":""}</i></button>}
function Field({label,children}:{label:string,children:React.ReactNode}){return <label className="admin-field"><b>{label}</b>{children}</label>}
function Metric({label,value,detail}:{label:string,value:string,detail:string}){return <div className="admin-metric"><small>{label}</small><b>{value}</b><span>{detail}</span></div>}
function EmptySettings({icon,title,description}:{icon:string,title:string,description:string}){return <section className="empty-settings"><span>{icon}</span><h2>{title}</h2><p>{description}</p><small>Reserved for the next implementation phase</small></section>}

function HouseholdAccess(){
  const [household,setHousehold]=useState<{name:string,slug:string}|null>(null),[name,setName]=useState(""),[invite,setInvite]=useState(""),[status,setStatus]=useState("");
  useEffect(()=>{api("/api/household").then(value=>{setHousehold(value);setName(value.name)}).catch(e=>setStatus(e instanceof Error?e.message:"Sign in required"))},[]);
  const saveName=async()=>{try{const value=await api("/api/household",{method:"PUT",body:JSON.stringify({name})});setHousehold(value);setStatus("Household name saved")}catch(e){setStatus(e instanceof Error?e.message:"Could not save")}};
  const createInvite=async()=>{try{const value=await api("/api/household/invitations",{method:"POST"});setInvite(value.invite_url);setStatus("Invitation created · expires in 24 hours")}catch(e){setStatus(e instanceof Error?e.message:"Could not create invitation")}};
  const copy=async()=>{await navigator.clipboard.writeText(invite);setStatus("Invitation link copied")};
  return <div className="settings-stack"><SettingCard title="Your household" description="People in one physical home share settings, rooms, history, and cooldowns."><Field label="Household name"><input value={name} onChange={e=>setName(e.target.value)} /></Field><button className="secondary-action" onClick={saveName}>Save household name</button></SettingCard><SettingCard title="Invite a household member" description="The invitee signs in with their own Plex account and must have access to this Plex server."><button className="secondary-action" onClick={createInvite}>Create one-time invitation</button>{invite&&<div className="household-invite"><input readOnly value={invite}/><button onClick={copy}>Copy link</button></div>}{status&&<small>{status}</small>}</SettingCard>{household&&<small>Household ID: {household.slug}</small>}</div>
}

function HouseholdJoin(){
  const token=new URLSearchParams(location.search).get("invite")||"";
  const [details,setDetails]=useState<{household_name:string}|null>(null),[auth,setAuth]=useState<{authenticated:boolean}>({authenticated:false}),[status,setStatus]=useState("");
  const refresh=()=>api("/api/auth/me").then(setAuth);
  useEffect(()=>{api(`/api/household/invitations/${encodeURIComponent(token)}`).then(setDetails).catch(e=>setStatus(e instanceof Error?e.message:"Invalid invitation"));refresh();const listener=()=>refresh();window.addEventListener("watchmatch-authenticated",listener);return()=>window.removeEventListener("watchmatch-authenticated",listener)},[]);
  const accept=async()=>{try{const value=await api(`/api/household/invitations/${encodeURIComponent(token)}/accept`,{method:"POST"});setStatus(`You joined ${value.household.name}.`)}catch(e){setStatus(e instanceof Error?e.message:"Could not join household")}};
  return <main className="center household-join"><div className="brand">WATCH<span>MATCH</span></div><div className="eyebrow">HOUSEHOLD INVITATION</div><h1>{details?`Join ${details.household_name}`:"Checking invitation…"}</h1><p>This connects your Plex identity to the same WatchMatch settings, rooms, and match history.</p>{details&&!auth.authenticated&&<p>Sign in with Plex using the button above, then return here.</p>}{details&&auth.authenticated&&<button className="primary" onClick={accept}>Join household</button>}{status&&<div className="share-status">{status}</div>}</main>
}

type AuthState={authenticated:boolean,required:boolean,username?:string};
const authCacheKey="watchmatch-auth-display-v1";
const readAuthDisplay=():AuthState|null=>{try{return JSON.parse(sessionStorage.getItem(authCacheKey)||"null")}catch{return null}};
function PlexGate({purpose="create rooms"}:{purpose?:string}){
  const [auth,setAuth]=useState<AuthState|null>(readAuthDisplay);
  const [busy,setBusy]=useState(false),[error,setError]=useState("");
  useEffect(()=>{api("/api/auth/me").then(value=>{setAuth(value);sessionStorage.setItem(authCacheKey,JSON.stringify(value))}).catch(()=>{})},[]);
  const signIn=async()=>{setBusy(true);setError("");let popup:Window|null=null;try{const started=await api("/api/auth/start",{method:"POST"});popup=window.open(started.auth_url,"plex-auth","width=760,height=720");if(!popup)throw new Error("Allow pop-ups to sign in with Plex");let pollDelay=3000;for(let attempt=0;attempt<300;attempt++){await new Promise(resolve=>setTimeout(resolve,pollDelay));if(popup.closed)throw new Error("Plex sign-in was canceled");const result=await api(`/api/auth/poll/${started.state}`);pollDelay=Math.max(3000,Math.min(30000,Number(result.retry_after||3)*1000));if(result.status==="authenticated"){popup.close();const current=await api("/api/auth/me");setAuth(current);sessionStorage.setItem(authCacheKey,JSON.stringify(current));window.dispatchEvent(new Event("watchmatch-authenticated"));setBusy(false);return}}throw new Error("Plex sign-in timed out")}catch(e){setError(e instanceof Error?e.message:"Could not sign in with Plex");setBusy(false)}};
  const logout=async()=>{await api("/api/auth/logout",{method:"POST"});const current={authenticated:false,required:true};setAuth(current);sessionStorage.setItem(authCacheKey,JSON.stringify(current));setError("");window.dispatchEvent(new Event("watchmatch-authenticated"))};
  if(!auth)return <div className="plex-gate plex-loading" aria-live="polite">Checking Plex…</div>;
  if(!auth.required)return null;
  return <div className="plex-gate">{auth.authenticated?<div className="plex-session"><span>✓ Signed in as {auth.username}</span><button onClick={logout}>Log out</button></div>:<button onClick={signIn} disabled={busy}>{busy?"Waiting for Plex…":`Sign in with Plex to ${purpose}`}</button>}{error&&<small>{error}</small>}</div>
}

function AdminGate(){
  const [auth,setAuth]=useState<{authenticated:boolean,required:boolean}|null>(null);
  const refresh=()=>api("/api/auth/me").then(setAuth).catch(()=>setAuth({authenticated:false,required:true}));
  useEffect(()=>{refresh();window.addEventListener("watchmatch-authenticated",refresh);return()=>window.removeEventListener("watchmatch-authenticated",refresh)},[]);
  if(!auth)return <main className="center settings-auth"><div className="brand">WATCH<span>MATCH</span></div><p>Checking your Plex session…</p></main>;
  if(auth.required&&!auth.authenticated)return <><PlexGate purpose="configure WatchMatch"/><main className="center settings-auth"><div className="brand">WATCH<span>MATCH</span></div><div className="eyebrow">CONFIGURATION &amp; SETTINGS</div><h1>Sign in to manage<br/>your household.</h1><p>Your settings belong to a WatchMatch household, so Plex sign-in is required before they can be viewed or changed.</p><a className="start-over" href="/">← Back to WatchMatch</a></main></>;
  return <Admin/>;
}

function SystemGate(){
  const [auth,setAuth]=useState<{authenticated:boolean,required:boolean}|null>(null);
  const [authorized,setAuthorized]=useState<boolean|null>(null);
  const [error,setError]=useState("");
  const [recoveryCode,setRecoveryCode]=useState(""),[recovering,setRecovering]=useState(false);
  const refresh=async()=>{setError("");setAuthorized(null);try{const current=await api("/api/auth/me");setAuth(current);if(!current.authenticated)return;await api("/api/system/access");setAuthorized(true)}catch(e){setAuthorized(false);setError(e instanceof Error?e.message:"System access denied")}};
  const recover=async()=>{setRecovering(true);setError("");try{await api("/api/system/recovery/session",{method:"POST",body:JSON.stringify({code:recoveryCode})});setRecoveryCode("");await refresh()}catch(e){setError(e instanceof Error?e.message:"Recovery failed")}finally{setRecovering(false)}};
  useEffect(()=>{refresh();window.addEventListener("watchmatch-authenticated",refresh);return()=>window.removeEventListener("watchmatch-authenticated",refresh)},[]);
  if(!auth||auth.authenticated&&authorized===null)return <main className="center settings-auth"><div className="brand">WATCH<span>MATCH</span></div><p>Verifying system-owner access…</p></main>;
  if(!auth.authenticated)return <><PlexGate purpose="access the system console"/><main className="center settings-auth"><div className="brand">WATCH<span>MATCH</span></div><div className="eyebrow">OWNER SYSTEM CONSOLE</div><h1>Owner sign-in<br/>required.</h1><p>This area controls the shared Plex catalog and WatchMatch infrastructure. Only the configured system owner can open it.</p><details className="recovery-code"><summary>Use emergency recovery code</summary><p>Use this only when Plex sign-in is unavailable. Access expires after 15 minutes.</p><input type="password" aria-label="Emergency recovery code" value={recoveryCode} onChange={e=>setRecoveryCode(e.target.value)} onKeyDown={e=>e.key==="Enter"&&recoveryCode&&recover()} autoComplete="off"/><button className="secondary-action" disabled={!recoveryCode||recovering} onClick={recover}>{recovering?"Recovering…":"Open system console"}</button>{error&&<small>{error}</small>}</details><a className="start-over" href="/">← Back to WatchMatch</a></main></>;
  if(!authorized)return <><PlexGate purpose="access the system console"/><main className="center settings-auth"><div className="brand">WATCH<span>MATCH</span></div><div className="eyebrow">OWNER SYSTEM CONSOLE</div><h1>This account cannot<br/>access the system.</h1><p>{error}</p><a className="start-over" href="/">← Back to WatchMatch</a></main></>;
  return <Admin system/>;
}

function App(){const p=location.pathname.split("/").filter(Boolean);return p[0]==="system"?<SystemGate/>:p[0]==="admin"?<AdminGate/>:p[0]==="household"&&p[1]==="join"?<><PlexGate/><HouseholdJoin/></>:p[0]==="room"?<RoomView code={p[1]?.toUpperCase()}/>:p[0]==="join"?<Join code={p[1]?.toUpperCase()}/>:<><PlexGate/><Home/><a className="admin-entry" href="/admin">Configuration &amp; Settings</a></>}createRoot(document.getElementById("root")!).render(<App/>);
